// -- Entry-path resolution ------------------------------------------------
// DripWebhook -> Verify JWT -> Tenant For JWT User -> here  (public HTTP)
// Called by Master Router -> here          (sub-workflow; already trusted)
//
// $('DripWebhook') THROWS when that node did not run in this execution -- it
// does NOT return undefined, so `?.` and `||` cannot rescue it, and an
// Expression field cannot hold try/catch. Removing this try/catch breaks the
// Master Router sub-workflow path.
let webhookJson = null;
try {
  webhookJson = $('DripWebhook').first().json;
} catch (e) {
  // sub-workflow path -- DripWebhook never executed.
}

let item;
if (webhookJson) {
  // 'Verify JWT' runs with onError = continueRegularOutput, so a rejected
  // token arrives as data. Supabase returns the user object on success.
  // This endpoint is fire-and-forget (the caller only ever sees
  // 'Workflow was started'), so a failed execution is the right signal.
  //
  // 18 Sep 2026: `Tenant For JWT User` was inserted between `Verify JWT`
  // and this node so that `Resolve Tenant` downstream can look the caller's
  // dealership up in tenant_members. That HTTP node REPLACES the item, so
  // the identity check can no longer read $input -- it reaches back to
  // `Verify JWT` by name. The guard itself is unchanged: no .id on the
  // verified user, no entry.
  let auth = {};
  try { auth = $('Verify JWT').first().json || {}; } catch (e) { auth = {}; }
  if (!auth.id) {
    // The '[NEXUS-UNATTRIBUTED]' prefix below is a contract with the NEXUS Error
    // Handler (iYJkh1kztWxZXDbT). An execution that failed BEFORE it authenticated
    // its caller belongs to no dealership, so that workflow omits tenant_id and
    // audit_log's own DEFAULT nexus_default_tenant_id() retains the row under the
    // quarantine tenant -- visible to nexus_quarantine_census(), unreadable by any
    // dealership -- instead of appending an anonymous stranger's row to ALBA CARS'
    // audit trail. Keep the marker at the START of the message: the handler tests
    // position 0, so a copy embedded in a request payload cannot trigger it.
    //
    // The two throws further down are deliberately NOT marked: a lead arriving
    // with no email is the dealership's own automation misfiring, and that row
    // belongs on the dealership's Automation screen.
    throw new Error('[NEXUS-UNATTRIBUTED] Drip campaign aborted: unauthorized. A valid Supabase session token is required in the Authorization header.');
  }
  item = webhookJson;
} else {
  item = $input.first().json;
}

// -- Normalise the lead ---------------------------------------------------
// Invoked two ways: webhook POST puts data under .body, the Master Router
// passes it under .lead. The dashboard posts lead_email / lead_name; the
// Master Router passes email / name. Both vocabularies are accepted.
let lead;
if (item.lead) {
  lead = item.lead;                 // Master Router sub-workflow call
} else if (item.body) {
  lead = item.body;                 // raw webhook POST
} else {
  lead = item;                      // already flat
}

const clean = (v) => (v === undefined || v === null || v === false || v === '') ? null : String(v).trim();

// `lead` can legitimately be a non-object here: a manual run from the n8n
// editor hands this node an empty item, and Object.keys(null) throws a
// TypeError that n8n surfaces as a bare "Unknown error [line N]" -- which is
// how a guard doing its job came to look like a broken node.
const leadKeys = (lead && typeof lead === 'object') ? Object.keys(lead) : [];

const email = clean(lead && lead.email) || clean(lead && lead.lead_email);
if (!email) {
  // This is not a fault. It is the node refusing to start a seven-day email
  // sequence aimed at nobody. Say which of the two situations it is, because
  // one needs fixing and the other is just the editor's Execute button.
  if (leadKeys.length === 0) {
    throw new Error(
      'Drip campaign not started: no lead was supplied. This workflow is ' +
      'triggered by a webhook (POST /webhook/lead-trigger) or called by the ' +
      'Master Router -- pressing Execute in the editor runs it with no input, ' +
      'so there is no lead to enrol and nothing was sent. To test it from the ' +
      'editor, pin data on this node with an email address on it.');
  }
  throw new Error(
    'Drip campaign not started: a lead arrived but carried no email address. ' +
    'Keys received: ' + leadKeys.join(', ') + '. Accepted field names are ' +
    'email or lead_email.');
}

return [{
  json: {
    name: clean(lead.name) || clean(lead.lead_name) || 'there',
    email: email,
    phone: clean(lead.phone) || clean(lead.whatsapp),
    vehicle_interest: clean(lead.vehicle_interest) || clean(lead.vehicleInterest) || clean(lead.message) || 'a vehicle',
    // Enrolment time, stamped once, here. Every gate compares inbound
    // communication_logs rows against this value to decide whether the customer
    // has answered since the sequence started, so it has to be ONE value read from
    // ONE place -- not $now evaluated separately in four nodes days apart, which
    // would move the goalposts forward every time a gate ran.
    enrolled_at: new Date().toISOString()
  }
}];

// Delivery Report - verify every claim the next node is about to make.
// The upstream sends run with onError:'continueRegularOutput'. A failure there
// is not an exception: n8n emits an item shaped { error: ... } on the main
// output and the run stays green. Nothing downstream ever looked at it, so the
// row written next asserted a send that may never have landed.
// The swallow is deliberate and stays. Only the unconditional claim goes.
// Only claim the WhatsApp legs when this lead actually took them. Both
// 'Has WhatsApp? (Day 1)' and 'Has WhatsApp? (Day 5)' branch on
// !!$('Normalize Lead Input').first().json.phone, so a lead with no phone
// legitimately never runs those nodes - claiming them unconditionally would
// report a false drop for every email-only lead.
const lead = (() => { try { return $('Normalize Lead Input').first().json || {}; }
                      catch (e) { return {}; } })();
// The phone is no longer only what the caller sent. The dashboard's enrolment
// payload carries lead_email / lead_name / vehicle_interest and no phone at all,
// so the number is read from the leads table by the gate nodes. Resolve it here
// exactly as the two 'Has WhatsApp?' gates and both WAHA sends do -- otherwise
// this report calls every dashboard-enrolled lead email-only and never checks the
// WhatsApp legs it actually ran.
const pick = (n) => { try { const v = $(n).first().json.phone; return v ? String(v).trim() : null; }
                      catch (e) { return null; } };
const hasWhatsApp = !!(pick('Lead State (Day 5)') || pick('Lead State (Day 1)') || pick('Normalize Lead Input'));

const CLAIMED = [
  { node: 'Email: Welcome (Gmail)', what: 'Day 1 welcome email', critical: true },
  { node: 'Log Welcome Email', what: 'Day 1 email communication_logs row', critical: false },
  { node: 'Email: Follow Up (Gmail)', what: 'Day 3 follow-up email', critical: true },
  { node: 'Log Follow Up Email', what: 'Day 3 email communication_logs row', critical: false },
  { node: 'Email: Final Offer (Gmail)', what: 'Day 7 final-offer email', critical: true },
  { node: 'Log Final Offer Email', what: 'Day 7 email communication_logs row', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);

if (hasWhatsApp) {
  results.push(check({ node: 'WhatsApp: Welcome',       what: 'Day 1 WhatsApp welcome',                 critical: true }));
  results.push(check({ node: 'Log WhatsApp Welcome',    what: 'Day 1 WhatsApp communication_logs row',  critical: false }));
  results.push(check({ node: 'WhatsApp: Check-in',      what: 'Day 5 WhatsApp check-in',                critical: true }));
  results.push(check({ node: 'Log WhatsApp Check-in',   what: 'Day 5 WhatsApp communication_logs row',  critical: false }));
}

const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  // 'Log Final Offer Email' sends Prefer: return=minimal, so the item arriving
  // here carries no lead fields whatsoever and the Audit Log node downstream was
  // writing lead_email: null on every completed run -- which is why finished
  // sequences could not be attached to anybody on the Campaigns roster. Name the
  // lead explicitly rather than hoping it survived the spread.
  lead_name: lead.name || null,
  lead_email: lead.email || null,
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' — ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
} }];

// Stopped Report - the sequence exited early, and that is the correct outcome.
//
// Reached only from the false output of a 'Still Enrolled? (Day N)' gate. The
// gates are four copies of one boolean; the prose lives here, once, so there is
// a single place to read what an exit means and a single place to change it.
//
// It answers three things in the shape 'Audit Log' already reads: which gate
// stopped the sequence, why, and what had actually gone out by then. check()
// and the status ladder are copied verbatim from 'Delivery Report' so that
// SUCCESS / PARTIAL / FAILED mean exactly one thing across this workflow.
//
// A deliberate stop is never FAILED. FAILED is reserved for a step that was
// attempted and did not land -- the Campaigns screen counts FAILED and REJECTED
// rows as failures against the lead, and a customer who bought the car is not a
// failure. Stopping always leaves something unsent, so an exit is PARTIAL.

const TERMINAL = ['WON','LOST','CLOSED','CONVERTED','DELIVERED','DEAD','JUNK','SPAM','UNQUALIFIED','ARCHIVED','DISQUALIFIED'];

// null  = that gate never executed in this run.
// []    = it ran and the query matched nothing.
const rowsOf = (n) => { try { return $(n).all().map(i => i.json).filter(r => r && r.id); }
                        catch (e) { return null; } };

const PHASES = [
  { day: 1, step: 'the day-1 welcome',      leadNode: 'Lead State (Day 1)', replyNode: 'Replies Since Enrol (Day 1)' },
  { day: 3, step: 'the day-3 follow-up',    leadNode: 'Lead State (Day 3)', replyNode: 'Replies Since Enrol (Day 3)' },
  { day: 5, step: 'the day-5 check-in',     leadNode: 'Lead State (Day 5)', replyNode: 'Replies Since Enrol (Day 5)' },
  { day: 7, step: 'the day-7 final offer',  leadNode: 'Lead State (Day 7)', replyNode: 'Replies Since Enrol (Day 7)' },
];

// The last gate that ran is the gate that stopped it.
let at = null;
for (const p of PHASES) {
  const rows = rowsOf(p.leadNode);
  if (rows === null) continue;
  at = { day: p.day, step: p.step, leadRow: rows[0] || null, replies: rowsOf(p.replyNode) || [] };
}

const reason = (() => {
  if (!at) return 'the gate that stopped the sequence could not be identified from this run';
  if (!at.leadRow) return 'the lead row no longer exists in the leads table';
  const st = String(at.leadRow.status || '').trim().toUpperCase();
  if (TERMINAL.includes(st)) return 'the lead status is ' + st + ', which is terminal';
  if (at.replies.length) {
    const r = at.replies[0];
    return 'the customer replied on ' + (r.created_at || 'an unrecorded date')
         + (r.channel ? ' by ' + r.channel : '')
         + ', so a person is already in the conversation';
  }
  return 'the gate returned false without naming a cause, which should not happen and is worth reading the execution for';
})();

// Same phone resolution as the two 'Has WhatsApp?' gates and both WAHA sends:
// the dashboard's enrolment payload carries no phone, so the number comes from
// the leads table via the gate reads.
const pick = (n) => { try { const v = $(n).first().json.phone; return v ? String(v).trim() : null; }
                      catch (e) { return null; } };
const hasWhatsApp = !!(pick('Lead State (Day 5)') || pick('Lead State (Day 1)') || pick('Normalize Lead Input'));

const SENT = [
  { day: 1, node: 'Email: Welcome (Gmail)',     what: 'Day 1 welcome email',                    critical: true  },
  { day: 1, node: 'Log Welcome Email',          what: 'Day 1 email communication_logs row',     critical: false },
  { day: 1, node: 'WhatsApp: Welcome',          what: 'Day 1 WhatsApp welcome',                 critical: true,  wa: true },
  { day: 1, node: 'Log WhatsApp Welcome',       what: 'Day 1 WhatsApp communication_logs row',  critical: false, wa: true },
  { day: 3, node: 'Email: Follow Up (Gmail)',   what: 'Day 3 follow-up email',                  critical: true  },
  { day: 3, node: 'Log Follow Up Email',        what: 'Day 3 email communication_logs row',     critical: false },
  { day: 5, node: 'WhatsApp: Check-in',         what: 'Day 5 WhatsApp check-in',                critical: true,  wa: true },
  { day: 5, node: 'Log WhatsApp Check-in',      what: 'Day 5 WhatsApp communication_logs row',  critical: false, wa: true },
  { day: 7, node: 'Email: Final Offer (Gmail)', what: 'Day 7 final-offer email',                critical: true  },
  { day: 7, node: 'Log Final Offer Email',      what: 'Day 7 email communication_logs row',     critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const stopDay   = at ? at.day : 1;
const relevant  = SENT.filter(c => !c.wa || hasWhatsApp);
const results   = relevant.filter(c => c.day <  stopDay).map(check);
const notSent   = relevant.filter(c => c.day >= stopDay).map(c => c.what + ' — not sent: ' + reason);

const failed  = results.filter(r => !r.ok);
const fatal   = failed.filter(r => r.critical);
const dropped = failed.map(r => r.what + ' — ' + r.why).concat(notSent);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

// Do NOT spread $input here. The item arriving from the gate is a
// communication_logs row, and that row carries its own lead_email -- which can
// be a WhatsApp chat id. Spreading it would file this audit row under a
// different key from the enrolment row and split one person into two on the
// Campaigns roster. Take the identity from the enrolment, explicitly.
const src = (() => { try { return $('Normalize Lead Input').first().json || {}; }
                     catch (e) { return {}; } })();

return [{ json: {
  lead_name: src.name || null,
  lead_email: src.email || null,
  name: src.name || null,
  email: src.email || null,
  vehicle_interest: src.vehicle_interest || null,
  enrolled_at: src.enrolled_at || null,
  exit_reason: reason,
  exit_step: at ? at.step : 'an unidentified step',
  exit_day: stopDay,
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped,
    note: 'stopped before ' + (at ? at.step : 'an unidentified step') + ' because ' + reason + '. '
        + (results.length
             ? results.filter(r => r.ok).length + ' of ' + results.length + ' steps already attempted were verified'
             : 'nothing had been sent yet')
        + '; ' + notSent.length + ' remaining step' + (notSent.length === 1 ? '' : 's') + ' will not be sent.',
  },
} }];

// NEXUS - Resolve Tenant (7-day drip)
// ---------------------------------------------------------------------------
// This workflow writes FIVE communication_logs rows per enrolled lead across
// seven days. n8n writes them as service_role, which is BYPASSRLS and has no
// auth.uid(), so without an explicit tenant_id the column default files each
// one under whichever tenant holds tenants.is_unattributed_default. A second
// dealership's cold lead would have its entire nurture thread appear in the
// FIRST dealership's Conversations screen, and be invisible in its own.
//
// TENANT (18 Sep 2026) ------------------------------------------------------
// REPLACES the 3 Sep resolver, which read the caller's tenant_id FIRST -- off
// the Master Router payload OR straight off the public webhook body -- and only
// then fell back to the configured map. On the public door that ordering was an
// open grant: anyone holding a valid Supabase session could POST
// /webhook/lead-trigger with `tenant_id: <someone else's dealership>` and have
// seven days of email and WhatsApp logged into that dealership's Conversations
// screen. The old comment named the hole ("NOT COVERED HERE: the public
// webhook's JWT is not mapped to a tenant") and left it open. The caller's
// tenant_id is never a source now. It is only ever a CLAIM, and a claim that
// disagrees with the membership row is refused.
//
// Two doors, two rules:
//   * public webhook -- `DripWebhook` -> `Verify JWT` -> `Tenant For JWT User`
//     -> `Normalize Lead Input` -> here. The ONLY trusted answer is the
//     tenant_members row for the Supabase user behind the verified JWT. No row,
//     or more than one row, means refuse; there is no fallback on this door,
//     because a fallback is exactly how an unverifiable caller acquires a
//     dealership.
//   * internal hop -- `Called by Master Router` -> `Normalize Lead Input` ->
//     here. The caller is a sibling workflow that already resolved the
//     dealership from the WAHA session the enquiry arrived on, so its UUID is
//     accepted. `Verify JWT` never ran on that path, and that is how this node
//     tells the two doors apart.
//
// Refusals carry the '[NEXUS-UNATTRIBUTED]' prefix at position 0, the contract
// with the NEXUS Error Handler (iYJkh1kztWxZXDbT): the failed execution is
// filed under the quarantine tenant instead of being appended to some real
// dealership's audit trail. Keep the marker at the START of the message -- the
// handler tests position 0, so a copy embedded in a request payload cannot
// trigger it.
const BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // ALBA CARS
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

let map = {};
try { map = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { map = {}; }
if (!map || typeof map !== 'object' || !Object.keys(map).length) map = BUILTIN;
const keys = Object.keys(map);

// What the caller ASSERTED, by whichever door it came in. Never authoritative:
// on the public door it is only ever cross-checked against the membership row,
// and on the internal door it comes from a workflow already inside the trust
// boundary. `$()` THROWS for a node that did not run in this execution -- it
// does not return undefined, so `?.` cannot stand in for the try/catch.
let claimed = '';
try {
  const j = $('Called by Master Router').first().json || {};
  claimed = String((j.lead && j.lead.tenant_id) || j.tenant_id || '');
} catch (e) { /* not the sub-workflow door */ }
if (!claimed) {
  try {
    const b = ($('DripWebhook').first().json || {}).body || {};
    claimed = String((b.lead && b.lead.tenant_id) || b.tenant_id || '');
  } catch (e) { /* not the webhook door */ }
}

// Which door? Same trick: `Verify JWT` only ever runs on the webhook branch.
let viaWebhook = true;
try { $('Verify JWT').all(); } catch (e) { viaWebhook = false; }

let tenant = null;
let source = 'unresolved';

if (viaWebhook) {
  const ids = Array.from(new Set(
    $('Tenant For JWT User').all()
      .map((i) => (i && i.json ? i.json.tenant_id : null))
      .filter(Boolean)
      .map(String)
  ));
  if (ids.length > 1) {
    throw new Error('[NEXUS-UNATTRIBUTED] Drip campaign aborted: the authenticated user is a member of ' + ids.length + ' dealerships. This endpoint will not choose one on their behalf.');
  }
  if (ids.length === 0 || !UUID.test(ids[0])) {
    throw new Error('[NEXUS-UNATTRIBUTED] Drip campaign aborted: the authenticated user has no tenant_members row. A dealership is never taken from the request body.');
  }
  if (claimed && claimed.toLowerCase() !== ids[0].toLowerCase()) {
    throw new Error('[NEXUS-UNATTRIBUTED] Drip campaign aborted: caller asserted tenant_id ' + claimed + ' but is a member of ' + ids[0] + '. tenant_id is not a caller-selectable field.');
  }
  tenant = ids[0];
  source = 'jwt_tenant_member';
} else {
  if (UUID.test(claimed)) {
    tenant = claimed;
    source = 'internal_caller';
  } else if (keys.length === 1 && UUID.test(String(map[keys[0]] || ''))) {
    tenant = String(map[keys[0]]);
    source = 'sole_configured_tenant';
  } else {
    throw new Error('[NEXUS-UNATTRIBUTED] Drip campaign aborted: the internal caller supplied no resolvable tenant_id and ' + keys.length + ' dealerships are configured. Refusing rather than enrolling this lead under a guess.');
  }
}

// Pass the enrolment payload through UNCHANGED apart from the two new keys:
// 'Audit: Enrolled' immediately downstream reads $json.name, $json.email and
// $json.enrolled_at off this item, and every later node reaches back to
// 'Normalize Lead Input' by name, which this node does not disturb.
return $input.all().map((item, i) => ({
  json: Object.assign({}, item.json, { tenant_id: tenant, tenant_source: source }),
  pairedItem: { item: i }
}));

// NX1007 -- per-dealer send channel resolution. FAIL CLOSED.
// Prefers WhatsApp Cloud (phone_number_id) over legacy WAHA session, per
// the channel_registry binding decision. No default, no shared session.
// An unresolved channel THROWS -- this workflow's errorWorkflow
// (iYJkh1kztWxZXDbT, NEXUS Error Handler) records it to audit_log. No send
// happens and the refusal is durable, not silent.
let rows = $input.all().map(i => i.json).filter(Boolean);
// PostgREST GET returns a JSON array; n8n normally splits it into one item
// per row, but defend the single-item-holding-an-array shape too.
if (rows.length === 1 && Array.isArray(rows[0])) rows = rows[0];
const cloud = rows.find(r => r.channel_type === 'whatsapp_cloud_phone_number_id');
const waha  = rows.find(r => r.channel_type === 'whatsapp_waha_session');
const picked = cloud || waha;
const tenantForLog = ($('Resolve Tenant').first().json.tenant_id || 'UNKNOWN');
if (!picked || !picked.external_identifier) {
  throw new Error('NX1007_NO_ACTIVE_CHANNEL: tenant ' + tenantForLog + ' has no active ' +
    'WhatsApp channel (Cloud or WAHA) in channel_registry. Refusing to send from a shared ' +
    'or default number. Register a channel via nexus_channel_secret_put / channel_registry ' +
    'before this dealership can receive outbound WhatsApp.');
}
let wahaKeyEnv = null;
if (picked.channel_type === 'whatsapp_waha_session') {
  const ref = String(picked.credential_ref || '');
  const m = ref.match(/^env:([A-Za-z0-9_]+)/);
  wahaKeyEnv = m ? m[1] : null;
  if (!wahaKeyEnv || !$env[wahaKeyEnv]) {
    throw new Error('NX1007_NO_ACTIVE_CHANNEL: tenant ' + tenantForLog + ' has a WAHA channel ' +
      'registered (' + picked.external_identifier + ') but its credential_ref (' + ref + ') does ' +
      'not resolve to a configured secret. Refusing to send.');
  }
}
const base = $('Resolve Tenant').first().json;
return [{ json: Object.assign({}, base, {
  send_provider: picked.channel_type,
  send_identifier: picked.external_identifier,
  waha_api_key_env: wahaKeyEnv
}) }];

// NX1007 -- per-dealer send channel resolution. FAIL CLOSED.
// Prefers WhatsApp Cloud (phone_number_id) over legacy WAHA session, per
// the channel_registry binding decision. No default, no shared session.
// An unresolved channel THROWS -- this workflow's errorWorkflow
// (iYJkh1kztWxZXDbT, NEXUS Error Handler) records it to audit_log. No send
// happens and the refusal is durable, not silent.
let rows = $input.all().map(i => i.json).filter(Boolean);
// PostgREST GET returns a JSON array; n8n normally splits it into one item
// per row, but defend the single-item-holding-an-array shape too.
if (rows.length === 1 && Array.isArray(rows[0])) rows = rows[0];
const cloud = rows.find(r => r.channel_type === 'whatsapp_cloud_phone_number_id');
const waha  = rows.find(r => r.channel_type === 'whatsapp_waha_session');
const picked = cloud || waha;
const tenantForLog = ($('Resolve Tenant').first().json.tenant_id || 'UNKNOWN');
if (!picked || !picked.external_identifier) {
  throw new Error('NX1007_NO_ACTIVE_CHANNEL: tenant ' + tenantForLog + ' has no active ' +
    'WhatsApp channel (Cloud or WAHA) in channel_registry. Refusing to send from a shared ' +
    'or default number. Register a channel via nexus_channel_secret_put / channel_registry ' +
    'before this dealership can receive outbound WhatsApp.');
}
let wahaKeyEnv = null;
if (picked.channel_type === 'whatsapp_waha_session') {
  const ref = String(picked.credential_ref || '');
  const m = ref.match(/^env:([A-Za-z0-9_]+)/);
  wahaKeyEnv = m ? m[1] : null;
  if (!wahaKeyEnv || !$env[wahaKeyEnv]) {
    throw new Error('NX1007_NO_ACTIVE_CHANNEL: tenant ' + tenantForLog + ' has a WAHA channel ' +
      'registered (' + picked.external_identifier + ') but its credential_ref (' + ref + ') does ' +
      'not resolve to a configured secret. Refusing to send.');
  }
}
const base = $('Resolve Tenant').first().json;
return [{ json: Object.assign({}, base, {
  send_provider: picked.channel_type,
  send_identifier: picked.external_identifier,
  waha_api_key_env: wahaKeyEnv
}) }];

// -- Entry-path resolution ------------------------------------------------
// DripWebhook -> Verify JWT -> Tenant For JWT User -> here  (public HTTP)
// Called by Master Router -> here          (sub-workflow; already trusted)
//
// $('DripWebhook') THROWS when that node did not run in this execution -- it
// does NOT return undefined, so `?.` and `||` cannot rescue it, and an
// Expression field cannot hold try/catch. Removing this try/catch breaks the
// Master Router sub-workflow path.
let webhookJson = null;
try {
  webhookJson = $('DripWebhook').first().json;
} catch (e) {
  // sub-workflow path -- DripWebhook never executed.
}

let item;
if (webhookJson) {
  // 'Verify JWT' runs with onError = continueRegularOutput, so a rejected
  // token arrives as data. Supabase returns the user object on success.
  // This endpoint is fire-and-forget (the caller only ever sees
  // 'Workflow was started'), so a failed execution is the right signal.
  //
  // 18 Sep 2026: `Tenant For JWT User` was inserted between `Verify JWT`
  // and this node so that `Resolve Tenant` downstream can look the caller's
  // dealership up in tenant_members. That HTTP node REPLACES the item, so
  // the identity check can no longer read $input -- it reaches back to
  // `Verify JWT` by name. The guard itself is unchanged: no .id on the
  // verified user, no entry.
  let auth = {};
  try { auth = $('Verify JWT').first().json || {}; } catch (e) { auth = {}; }
  if (!auth.id) {
    // The '[NEXUS-UNATTRIBUTED]' prefix below is a contract with the NEXUS Error
    // Handler (iYJkh1kztWxZXDbT). An execution that failed BEFORE it authenticated
    // its caller belongs to no dealership, so that workflow omits tenant_id and
    // audit_log's own DEFAULT nexus_default_tenant_id() retains the row under the
    // quarantine tenant -- visible to nexus_quarantine_census(), unreadable by any
    // dealership -- instead of appending an anonymous stranger's row to ALBA CARS'
    // audit trail. Keep the marker at the START of the message: the handler tests
    // position 0, so a copy embedded in a request payload cannot trigger it.
    //
    // The two throws further down are deliberately NOT marked: a lead arriving
    // with no email is the dealership's own automation misfiring, and that row
    // belongs on the dealership's Automation screen.
    throw new Error('[NEXUS-UNATTRIBUTED] Drip campaign aborted: unauthorized. A valid Supabase session token is required in the Authorization header.');
  }
  item = webhookJson;
} else {
  item = $input.first().json;
}

// -- Normalise the lead ---------------------------------------------------
// Invoked two ways: webhook POST puts data under .body, the Master Router
// passes it under .lead. The dashboard posts lead_email / lead_name; the
// Master Router passes email / name. Both vocabularies are accepted.
let lead;
if (item.lead) {
  lead = item.lead;                 // Master Router sub-workflow call
} else if (item.body) {
  lead = item.body;                 // raw webhook POST
} else {
  lead = item;                      // already flat
}

const clean = (v) => (v === undefined || v === null || v === false || v === '') ? null : String(v).trim();

// `lead` can legitimately be a non-object here: a manual run from the n8n
// editor hands this node an empty item, and Object.keys(null) throws a
// TypeError that n8n surfaces as a bare "Unknown error [line N]" -- which is
// how a guard doing its job came to look like a broken node.
const leadKeys = (lead && typeof lead === 'object') ? Object.keys(lead) : [];

const email = clean(lead && lead.email) || clean(lead && lead.lead_email);
if (!email) {
  // This is not a fault. It is the node refusing to start a seven-day email
  // sequence aimed at nobody. Say which of the two situations it is, because
  // one needs fixing and the other is just the editor's Execute button.
  if (leadKeys.length === 0) {
    throw new Error(
      'Drip campaign not started: no lead was supplied. This workflow is ' +
      'triggered by a webhook (POST /webhook/lead-trigger) or called by the ' +
      'Master Router -- pressing Execute in the editor runs it with no input, ' +
      'so there is no lead to enrol and nothing was sent. To test it from the ' +
      'editor, pin data on this node with an email address on it.');
  }
  throw new Error(
    'Drip campaign not started: a lead arrived but carried no email address. ' +
    'Keys received: ' + leadKeys.join(', ') + '. Accepted field names are ' +
    'email or lead_email.');
}

return [{
  json: {
    name: clean(lead.name) || clean(lead.lead_name) || 'there',
    email: email,
    phone: clean(lead.phone) || clean(lead.whatsapp),
    vehicle_interest: clean(lead.vehicle_interest) || clean(lead.vehicleInterest) || clean(lead.message) || 'a vehicle',
    // Enrolment time, stamped once, here. Every gate compares inbound
    // communication_logs rows against this value to decide whether the customer
    // has answered since the sequence started, so it has to be ONE value read from
    // ONE place -- not $now evaluated separately in four nodes days apart, which
    // would move the goalposts forward every time a gate ran.
    enrolled_at: new Date().toISOString()
  }
}];

// Delivery Report - verify every claim the next node is about to make.
// The upstream sends run with onError:'continueRegularOutput'. A failure there
// is not an exception: n8n emits an item shaped { error: ... } on the main
// output and the run stays green. Nothing downstream ever looked at it, so the
// row written next asserted a send that may never have landed.
// The swallow is deliberate and stays. Only the unconditional claim goes.
// Only claim the WhatsApp legs when this lead actually took them. Both
// 'Has WhatsApp? (Day 1)' and 'Has WhatsApp? (Day 5)' branch on
// !!$('Normalize Lead Input').first().json.phone, so a lead with no phone
// legitimately never runs those nodes - claiming them unconditionally would
// report a false drop for every email-only lead.
const lead = (() => { try { return $('Normalize Lead Input').first().json || {}; }
                      catch (e) { return {}; } })();
// The phone is no longer only what the caller sent. The dashboard's enrolment
// payload carries lead_email / lead_name / vehicle_interest and no phone at all,
// so the number is read from the leads table by the gate nodes. Resolve it here
// exactly as the two 'Has WhatsApp?' gates and both WAHA sends do -- otherwise
// this report calls every dashboard-enrolled lead email-only and never checks the
// WhatsApp legs it actually ran.
const pick = (n) => { try { const v = $(n).first().json.phone; return v ? String(v).trim() : null; }
                      catch (e) { return null; } };
const hasWhatsApp = !!(pick('Lead State (Day 5)') || pick('Lead State (Day 1)') || pick('Normalize Lead Input'));

const CLAIMED = [
  { node: 'Email: Welcome (Gmail)', what: 'Day 1 welcome email', critical: true },
  { node: 'Log Welcome Email', what: 'Day 1 email communication_logs row', critical: false },
  { node: 'Email: Follow Up (Gmail)', what: 'Day 3 follow-up email', critical: true },
  { node: 'Log Follow Up Email', what: 'Day 3 email communication_logs row', critical: false },
  { node: 'Email: Final Offer (Gmail)', what: 'Day 7 final-offer email', critical: true },
  { node: 'Log Final Offer Email', what: 'Day 7 email communication_logs row', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);

if (hasWhatsApp) {
  results.push(check({ node: 'WhatsApp: Welcome',       what: 'Day 1 WhatsApp welcome',                 critical: true }));
  results.push(check({ node: 'Log WhatsApp Welcome',    what: 'Day 1 WhatsApp communication_logs row',  critical: false }));
  results.push(check({ node: 'WhatsApp: Check-in',      what: 'Day 5 WhatsApp check-in',                critical: true }));
  results.push(check({ node: 'Log WhatsApp Check-in',   what: 'Day 5 WhatsApp communication_logs row',  critical: false }));
}

const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  // 'Log Final Offer Email' sends Prefer: return=minimal, so the item arriving
  // here carries no lead fields whatsoever and the Audit Log node downstream was
  // writing lead_email: null on every completed run -- which is why finished
  // sequences could not be attached to anybody on the Campaigns roster. Name the
  // lead explicitly rather than hoping it survived the spread.
  lead_name: lead.name || null,
  lead_email: lead.email || null,
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' — ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
} }];

// Stopped Report - the sequence exited early, and that is the correct outcome.
//
// Reached only from the false output of a 'Still Enrolled? (Day N)' gate. The
// gates are four copies of one boolean; the prose lives here, once, so there is
// a single place to read what an exit means and a single place to change it.
//
// It answers three things in the shape 'Audit Log' already reads: which gate
// stopped the sequence, why, and what had actually gone out by then. check()
// and the status ladder are copied verbatim from 'Delivery Report' so that
// SUCCESS / PARTIAL / FAILED mean exactly one thing across this workflow.
//
// A deliberate stop is never FAILED. FAILED is reserved for a step that was
// attempted and did not land -- the Campaigns screen counts FAILED and REJECTED
// rows as failures against the lead, and a customer who bought the car is not a
// failure. Stopping always leaves something unsent, so an exit is PARTIAL.

const TERMINAL = ['WON','LOST','CLOSED','CONVERTED','DELIVERED','DEAD','JUNK','SPAM','UNQUALIFIED','ARCHIVED','DISQUALIFIED'];

// null  = that gate never executed in this run.
// []    = it ran and the query matched nothing.
const rowsOf = (n) => { try { return $(n).all().map(i => i.json).filter(r => r && r.id); }
                        catch (e) { return null; } };

const PHASES = [
  { day: 1, step: 'the day-1 welcome',      leadNode: 'Lead State (Day 1)', replyNode: 'Replies Since Enrol (Day 1)' },
  { day: 3, step: 'the day-3 follow-up',    leadNode: 'Lead State (Day 3)', replyNode: 'Replies Since Enrol (Day 3)' },
  { day: 5, step: 'the day-5 check-in',     leadNode: 'Lead State (Day 5)', replyNode: 'Replies Since Enrol (Day 5)' },
  { day: 7, step: 'the day-7 final offer',  leadNode: 'Lead State (Day 7)', replyNode: 'Replies Since Enrol (Day 7)' },
];

// The last gate that ran is the gate that stopped it.
let at = null;
for (const p of PHASES) {
  const rows = rowsOf(p.leadNode);
  if (rows === null) continue;
  at = { day: p.day, step: p.step, leadRow: rows[0] || null, replies: rowsOf(p.replyNode) || [] };
}

const reason = (() => {
  if (!at) return 'the gate that stopped the sequence could not be identified from this run';
  if (!at.leadRow) return 'the lead row no longer exists in the leads table';
  const st = String(at.leadRow.status || '').trim().toUpperCase();
  if (TERMINAL.includes(st)) return 'the lead status is ' + st + ', which is terminal';
  if (at.replies.length) {
    const r = at.replies[0];
    return 'the customer replied on ' + (r.created_at || 'an unrecorded date')
         + (r.channel ? ' by ' + r.channel : '')
         + ', so a person is already in the conversation';
  }
  return 'the gate returned false without naming a cause, which should not happen and is worth reading the execution for';
})();

// Same phone resolution as the two 'Has WhatsApp?' gates and both WAHA sends:
// the dashboard's enrolment payload carries no phone, so the number comes from
// the leads table via the gate reads.
const pick = (n) => { try { const v = $(n).first().json.phone; return v ? String(v).trim() : null; }
                      catch (e) { return null; } };
const hasWhatsApp = !!(pick('Lead State (Day 5)') || pick('Lead State (Day 1)') || pick('Normalize Lead Input'));

const SENT = [
  { day: 1, node: 'Email: Welcome (Gmail)',     what: 'Day 1 welcome email',                    critical: true  },
  { day: 1, node: 'Log Welcome Email',          what: 'Day 1 email communication_logs row',     critical: false },
  { day: 1, node: 'WhatsApp: Welcome',          what: 'Day 1 WhatsApp welcome',                 critical: true,  wa: true },
  { day: 1, node: 'Log WhatsApp Welcome',       what: 'Day 1 WhatsApp communication_logs row',  critical: false, wa: true },
  { day: 3, node: 'Email: Follow Up (Gmail)',   what: 'Day 3 follow-up email',                  critical: true  },
  { day: 3, node: 'Log Follow Up Email',        what: 'Day 3 email communication_logs row',     critical: false },
  { day: 5, node: 'WhatsApp: Check-in',         what: 'Day 5 WhatsApp check-in',                critical: true,  wa: true },
  { day: 5, node: 'Log WhatsApp Check-in',      what: 'Day 5 WhatsApp communication_logs row',  critical: false, wa: true },
  { day: 7, node: 'Email: Final Offer (Gmail)', what: 'Day 7 final-offer email',                critical: true  },
  { day: 7, node: 'Log Final Offer Email',      what: 'Day 7 email communication_logs row',     critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const stopDay   = at ? at.day : 1;
const relevant  = SENT.filter(c => !c.wa || hasWhatsApp);
const results   = relevant.filter(c => c.day <  stopDay).map(check);
const notSent   = relevant.filter(c => c.day >= stopDay).map(c => c.what + ' — not sent: ' + reason);

const failed  = results.filter(r => !r.ok);
const fatal   = failed.filter(r => r.critical);
const dropped = failed.map(r => r.what + ' — ' + r.why).concat(notSent);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

// Do NOT spread $input here. The item arriving from the gate is a
// communication_logs row, and that row carries its own lead_email -- which can
// be a WhatsApp chat id. Spreading it would file this audit row under a
// different key from the enrolment row and split one person into two on the
// Campaigns roster. Take the identity from the enrolment, explicitly.
const src = (() => { try { return $('Normalize Lead Input').first().json || {}; }
                     catch (e) { return {}; } })();

return [{ json: {
  lead_name: src.name || null,
  lead_email: src.email || null,
  name: src.name || null,
  email: src.email || null,
  vehicle_interest: src.vehicle_interest || null,
  enrolled_at: src.enrolled_at || null,
  exit_reason: reason,
  exit_step: at ? at.step : 'an unidentified step',
  exit_day: stopDay,
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped,
    note: 'stopped before ' + (at ? at.step : 'an unidentified step') + ' because ' + reason + '. '
        + (results.length
             ? results.filter(r => r.ok).length + ' of ' + results.length + ' steps already attempted were verified'
             : 'nothing had been sent yet')
        + '; ' + notSent.length + ' remaining step' + (notSent.length === 1 ? '' : 's') + ' will not be sent.',
  },
} }];

// NEXUS - Resolve Tenant (7-day drip)
// ---------------------------------------------------------------------------
// This workflow writes FIVE communication_logs rows per enrolled lead across
// seven days. n8n writes them as service_role, which is BYPASSRLS and has no
// auth.uid(), so without an explicit tenant_id the column default files each
// one under whichever tenant holds tenants.is_unattributed_default. A second
// dealership's cold lead would have its entire nurture thread appear in the
// FIRST dealership's Conversations screen, and be invisible in its own.
//
// TENANT (18 Sep 2026) ------------------------------------------------------
// REPLACES the 3 Sep resolver, which read the caller's tenant_id FIRST -- off
// the Master Router payload OR straight off the public webhook body -- and only
// then fell back to the configured map. On the public door that ordering was an
// open grant: anyone holding a valid Supabase session could POST
// /webhook/lead-trigger with `tenant_id: <someone else's dealership>` and have
// seven days of email and WhatsApp logged into that dealership's Conversations
// screen. The old comment named the hole ("NOT COVERED HERE: the public
// webhook's JWT is not mapped to a tenant") and left it open. The caller's
// tenant_id is never a source now. It is only ever a CLAIM, and a claim that
// disagrees with the membership row is refused.
//
// Two doors, two rules:
//   * public webhook -- `DripWebhook` -> `Verify JWT` -> `Tenant For JWT User`
//     -> `Normalize Lead Input` -> here. The ONLY trusted answer is the
//     tenant_members row for the Supabase user behind the verified JWT. No row,
//     or more than one row, means refuse; there is no fallback on this door,
//     because a fallback is exactly how an unverifiable caller acquires a
//     dealership.
//   * internal hop -- `Called by Master Router` -> `Normalize Lead Input` ->
//     here. The caller is a sibling workflow that already resolved the
//     dealership from the WAHA session the enquiry arrived on, so its UUID is
//     accepted. `Verify JWT` never ran on that path, and that is how this node
//     tells the two doors apart.
//
// Refusals carry the '[NEXUS-UNATTRIBUTED]' prefix at position 0, the contract
// with the NEXUS Error Handler (iYJkh1kztWxZXDbT): the failed execution is
// filed under the quarantine tenant instead of being appended to some real
// dealership's audit trail. Keep the marker at the START of the message -- the
// handler tests position 0, so a copy embedded in a request payload cannot
// trigger it.
const BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // ALBA CARS
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

let map = {};
try { map = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { map = {}; }
if (!map || typeof map !== 'object' || !Object.keys(map).length) map = BUILTIN;
const keys = Object.keys(map);

// What the caller ASSERTED, by whichever door it came in. Never authoritative:
// on the public door it is only ever cross-checked against the membership row,
// and on the internal door it comes from a workflow already inside the trust
// boundary. `$()` THROWS for a node that did not run in this execution -- it
// does not return undefined, so `?.` cannot stand in for the try/catch.
let claimed = '';
try {
  const j = $('Called by Master Router').first().json || {};
  claimed = String((j.lead && j.lead.tenant_id) || j.tenant_id || '');
} catch (e) { /* not the sub-workflow door */ }
if (!claimed) {
  try {
    const b = ($('DripWebhook').first().json || {}).body || {};
    claimed = String((b.lead && b.lead.tenant_id) || b.tenant_id || '');
  } catch (e) { /* not the webhook door */ }
}

// Which door? Same trick: `Verify JWT` only ever runs on the webhook branch.
let viaWebhook = true;
try { $('Verify JWT').all(); } catch (e) { viaWebhook = false; }

let tenant = null;
let source = 'unresolved';

if (viaWebhook) {
  const ids = Array.from(new Set(
    $('Tenant For JWT User').all()
      .map((i) => (i && i.json ? i.json.tenant_id : null))
      .filter(Boolean)
      .map(String)
  ));
  if (ids.length > 1) {
    throw new Error('[NEXUS-UNATTRIBUTED] Drip campaign aborted: the authenticated user is a member of ' + ids.length + ' dealerships. This endpoint will not choose one on their behalf.');
  }
  if (ids.length === 0 || !UUID.test(ids[0])) {
    throw new Error('[NEXUS-UNATTRIBUTED] Drip campaign aborted: the authenticated user has no tenant_members row. A dealership is never taken from the request body.');
  }
  if (claimed && claimed.toLowerCase() !== ids[0].toLowerCase()) {
    throw new Error('[NEXUS-UNATTRIBUTED] Drip campaign aborted: caller asserted tenant_id ' + claimed + ' but is a member of ' + ids[0] + '. tenant_id is not a caller-selectable field.');
  }
  tenant = ids[0];
  source = 'jwt_tenant_member';
} else {
  if (UUID.test(claimed)) {
    tenant = claimed;
    source = 'internal_caller';
  } else if (keys.length === 1 && UUID.test(String(map[keys[0]] || ''))) {
    tenant = String(map[keys[0]]);
    source = 'sole_configured_tenant';
  } else {
    throw new Error('[NEXUS-UNATTRIBUTED] Drip campaign aborted: the internal caller supplied no resolvable tenant_id and ' + keys.length + ' dealerships are configured. Refusing rather than enrolling this lead under a guess.');
  }
}

// Pass the enrolment payload through UNCHANGED apart from the two new keys:
// 'Audit: Enrolled' immediately downstream reads $json.name, $json.email and
// $json.enrolled_at off this item, and every later node reaches back to
// 'Normalize Lead Input' by name, which this node does not disturb.
return $input.all().map((item, i) => ({
  json: Object.assign({}, item.json, { tenant_id: tenant, tenant_source: source }),
  pairedItem: { item: i }
}));
